<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Malaria Poster</title>
  <script src="/app/vendor/infographic.min.js"></script>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap');

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      width: 2480px;
      min-height: 3508px;
      background: #0b1120;
      font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
      color: #f1f5f9;
      overflow-x: hidden;
    }

    /* ── TOP BANNER ── */
    .top-banner {
      width: 100%;
      background: linear-gradient(135deg, #0f1f3d 0%, #1a1040 100%);
      padding: 80px 160px 60px;
      border-bottom: 6px solid #f59e0b;
      position: relative;
    }
    .top-banner::after {
      content: '';
      position: absolute;
      bottom: -6px; left: 0; right: 0;
      height: 3px;
      background: linear-gradient(90deg, #ef4444, #f59e0b, #22c55e);
    }
    .banner-overline {
      font-size: 28px;
      font-weight: 600;
      letter-spacing: 5px;
      text-transform: uppercase;
      color: #f59e0b;
      margin-bottom: 28px;
    }
    .banner-title {
      font-size: 96px;
      font-weight: 900;
      line-height: 1.05;
      color: #ffffff;
      letter-spacing: -2px;
      margin-bottom: 36px;
    }
    .banner-title span { color: #ef4444; }
    .banner-subtitle {
      font-size: 36px;
      font-weight: 400;
      color: #94a3b8;
      max-width: 1600px;
      line-height: 1.6;
    }
    .banner-badge {
      position: absolute;
      top: 80px; right: 160px;
      background: rgba(239,68,68,0.12);
      border: 3px solid #ef4444;
      border-radius: 24px;
      padding: 32px 48px;
      text-align: center;
    }
    .banner-badge .num {
      font-size: 88px;
      font-weight: 900;
      color: #ef4444;
      line-height: 1;
      display: block;
    }
    .banner-badge .lbl {
      font-size: 26px;
      font-weight: 600;
      color: #fca5a5;
      margin-top: 8px;
    }

    /* ── SECTION CONTAINERS ── */
    .poster-body {
      padding: 80px 160px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px 80px;
    }
    .section-card {
      background: rgba(255,255,255,0.03);
      border: 1.5px solid rgba(255,255,255,0.08);
      border-radius: 20px;
      padding: 56px 60px;
      position: relative;
    }
    .section-card.full-width {
      grid-column: 1 / -1;
    }
    .section-card.accent-red { border-top: 5px solid #ef4444; }
    .section-card.accent-amber { border-top: 5px solid #f59e0b; }
    .section-card.accent-green { border-top: 5px solid #22c55e; }
    .section-card.accent-blue { border-top: 5px solid #60a5fa; }

    .section-label {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: 4px;
      text-transform: uppercase;
      color: #64748b;
      margin-bottom: 18px;
    }
    .section-title {
      font-size: 42px;
      font-weight: 800;
      color: #f1f5f9;
      margin-bottom: 28px;
      line-height: 1.2;
    }
    .section-body {
      font-size: 26px;
      color: #94a3b8;
      line-height: 1.7;
    }

    /* ── HERO STAT ── */
    .hero-stat-block {
      grid-column: 1 / -1;
      background: linear-gradient(135deg, #1a0808 0%, #2d1010 100%);
      border: 3px solid #ef4444;
      border-radius: 24px;
      padding: 80px 120px;
      display: flex;
      align-items: center;
      gap: 80px;
    }
    .hero-stat-number {
      font-size: 180px;
      font-weight: 900;
      color: #ef4444;
      line-height: 1;
      white-space: nowrap;
      text-shadow: 0 0 80px rgba(239,68,68,0.4);
    }
    .hero-stat-right { flex: 1; }
    .hero-stat-title {
      font-size: 56px;
      font-weight: 800;
      color: #ffffff;
      margin-bottom: 20px;
      line-height: 1.2;
    }
    .hero-stat-desc {
      font-size: 30px;
      color: #fca5a5;
      line-height: 1.6;
    }

    /* ── METRICS GRID ── */
    .metrics-row {
      grid-column: 1 / -1;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
    }
    .metric-tile {
      background: rgba(255,255,255,0.04);
      border: 1.5px solid rgba(255,255,255,0.1);
      border-radius: 16px;
      padding: 40px 44px;
      text-align: center;
    }
    .metric-value {
      font-size: 64px;
      font-weight: 900;
      line-height: 1;
      margin-bottom: 12px;
    }
    .metric-label {
      font-size: 22px;
      font-weight: 600;
      color: #cbd5e1;
      margin-bottom: 8px;
    }
    .metric-context {
      font-size: 19px;
      color: #64748b;
    }

    /* ── COMPARE BAR ── */
    .compare-section { grid-column: 1 / -1; }
    .compare-title { font-size: 44px; font-weight: 800; color: #f1f5f9; margin-bottom: 12px; }
    .compare-subtitle { font-size: 26px; color: #94a3b8; margin-bottom: 48px; line-height: 1.5; }
    .compare-bars { display: flex; flex-direction: column; gap: 36px; }
    .bar-row { display: flex; align-items: center; gap: 32px; }
    .bar-era { font-size: 24px; font-weight: 700; color: #cbd5e1; width: 340px; flex-shrink: 0; text-align: right; }
    .bar-track { flex: 1; background: rgba(255,255,255,0.06); border-radius: 8px; height: 52px; position: relative; overflow: hidden; }
    .bar-fill { height: 100%; border-radius: 8px; display: flex; align-items: center; padding-left: 20px; font-size: 26px; font-weight: 800; color: #0b1120; }
    .bar-pct { position: absolute; right: 16px; top: 50%; transform: translateY(-50%); font-size: 22px; color: #94a3b8; font-weight: 600; }
    .bar-note { font-size: 21px; color: #64748b; width: 280px; flex-shrink: 0; }

    /* ── TREND CHART ── */
    .chart-section { grid-column: 1 / -1; }
    .chart-title { font-size: 44px; font-weight: 800; color: #f1f5f9; margin-bottom: 12px; }
    .chart-subtitle { font-size: 26px; color: #94a3b8; margin-bottom: 52px; line-height: 1.5; }
    .chart-area { position: relative; height: 380px; }
    .chart-svg { width: 100%; height: 100%; }
    .phase-label {
      position: absolute;
      font-size: 19px;
      font-weight: 700;
      letter-spacing: 2px;
      text-transform: uppercase;
      padding: 6px 14px;
      border-radius: 6px;
    }

    /* ── INTERVENTIONS ── */
    .interventions-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      margin-top: 8px;
    }
    .intervention-card {
      background: rgba(245,158,11,0.05);
      border: 2px solid rgba(245,158,11,0.2);
      border-radius: 16px;
      padding: 44px 40px;
    }
    .intervention-icon {
      font-size: 52px;
      margin-bottom: 20px;
    }
    .intervention-name {
      font-size: 28px;
      font-weight: 700;
      color: #f59e0b;
      margin-bottom: 14px;
    }
    .intervention-desc {
      font-size: 22px;
      color: #94a3b8;
      line-height: 1.6;
    }

    /* ── CALL TO ACTION ── */
    .cta-section {
      grid-column: 1 / -1;
      background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
      border-radius: 24px;
      padding: 80px 120px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 60px;
    }
    .cta-left { flex: 1; }
    .cta-title {
      font-size: 64px;
      font-weight: 900;
      color: #0b1120;
      line-height: 1.1;
      margin-bottom: 24px;
    }
    .cta-body {
      font-size: 28px;
      color: #1c2535;
      line-height: 1.6;
    }
    .cta-facts { display: flex; flex-direction: column; gap: 24px; min-width: 520px; }
    .cta-fact {
      background: rgba(0,0,0,0.12);
      border-radius: 12px;
      padding: 28px 36px;
      display: flex;
      align-items: center;
      gap: 24px;
    }
    .cta-fact-icon { font-size: 36px; }
    .cta-fact-text { font-size: 22px; font-weight: 600; color: #0b1120; line-height: 1.4; }

    /* ── FOOTER ── */
    .poster-footer {
      border-top: 2px solid rgba(255,255,255,0.08);
      padding: 40px 160px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .footer-source { font-size: 19px; color: #475569; }
    .footer-logo { font-size: 22px; font-weight: 700; color: #334155; letter-spacing: 2px; }
  </style>
</head>
